import puppeteer from 'puppeteer-core';
const url=process.env.TEST_URL,executablePath=process.env.CHROME_PATH;if(!url||!executablePath)throw new Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],timeout:30000});
const context=await browser.createBrowserContext();const page=await context.newPage();const errors=[];
page.on('pageerror',e=>errors.push(String(e?.stack||e?.message||e)));page.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource:.*404/i.test(m.text()))errors.push('console: '+m.text())});
await page.evaluateOnNewDocument(()=>{try{localStorage.setItem('BombermanPlayerName','RatingCI');localStorage.setItem('BombermanRatingV1','500');localStorage.removeItem('BombermanCharacterV1')}catch(e){}try{if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({scope:location.href})}catch(e){}});
try{
 await page.goto(url,{waitUntil:'domcontentloaded',timeout:20000});
 await page.waitForFunction(()=>window.BomberCharacter&&document.getElementById('buildVersion123')?.textContent==='v0.12.3'&&window.BomberQOL?.bottomRightOpponent&&gGameEngine?.menu&&Menu.prototype.__v123HitAreaFix,{timeout:16000});
 await page.evaluate(()=>{if(!gGameEngine.menu.views.length)gGameEngine.menu.show()});await sleep(100);
 const menu=await page.evaluate(()=>({version:document.getElementById('buildVersion123')?.textContent,characterPanel:!!document.getElementById('characterPanel'),rating:BomberCharacter.getRating(),menuViews:gGameEngine.menu.views.length}));
 console.log('CHAR_BOOT',JSON.stringify(menu));if(menu.version!=='v0.12.3'||!menu.characterPanel||menu.rating!==500||menu.menuViews<1)throw new Error('character/rating runtime did not boot');
 const hit=await page.evaluate(()=>{const shapes=gGameEngine.menu.views.filter(v=>v instanceof createjs.Shape&&v._listeners?.click?.length);const cards=gGameEngine.menu.views.filter(v=>v instanceof createjs.Container&&v._listeners?.click?.length);return{shapeX:shapes.map(v=>v.x),cardX:cards.map(v=>v.x)}});
 console.log('MENU_HIT_AREAS',JSON.stringify(hit));if(hit.shapeX.length<2||hit.shapeX[0]!==-50||hit.shapeX[1]!==50||hit.cardX.length<1)throw new Error('Single/Online/Character hit areas are not separated');
 await page.evaluate(()=>{const shapes=gGameEngine.menu.views.filter(v=>v instanceof createjs.Shape&&v._listeners?.click?.length);shapes[1].dispatchEvent('click')});await sleep(100);const onlineOpen=await page.evaluate(()=>!B115.els.lobby.hidden);if(!onlineOpen)throw new Error('Online multiplayer menu hit area did not open lobby');
 await page.evaluate(()=>{B115.destroyNetwork();B115.setRole('offline');B115.els.lobby.hidden=true;gGameEngine.lobbyOpen=false;gGameEngine.menu.show()});await sleep(100);
 await page.evaluate(()=>{const card=gGameEngine.menu.views.find(v=>v instanceof createjs.Container&&v._listeners?.click?.length);if(!card)throw new Error('Character card click target missing');card.dispatchEvent('click')});await sleep(100);
 const panel=await page.evaluate(()=>({hidden:document.getElementById('characterPanel').hidden,genders:document.querySelectorAll('[data-char-gender]').length,skins:document.querySelectorAll('[data-char-skin]').length,hats:document.querySelectorAll('[data-char-hat]').length,shoes:document.querySelectorAll('[data-char-shoes]').length,rating:document.getElementById('characterPreviewRating')?.textContent}));
 console.log('CHAR_PANEL',JSON.stringify(panel));if(panel.hidden||panel.genders!==2||panel.skins!==5||panel.hats!==3||panel.shoes!==5||!panel.rating.includes('500'))throw new Error('character options missing');
 await page.click('#characterRandom');await sleep(60);const previewAlpha=await page.evaluate(()=>{const c=document.getElementById('characterPreview'),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let a=0;for(let i=3;i<d.length;i+=4)a+=d[i];return a});if(previewAlpha<=0)throw new Error('character preview blank');await page.click('#characterClose');
 await page.evaluate(()=>{if(B115.els?.name)B115.els.name.value='RatingCI';B115.localName='RatingCI';B115.kind='public';B115.setRole('host');B115.startSimulated()});await sleep(650);
 const sim=await page.evaluate(()=>{const s=gGameEngine.simulatedOpponent;return{role:B115.role,name:B115.remoteName,rating:s?.rating,skill:s?.humanSkill,tier:s?.skillTier,x:s?.position.x,y:s?.position.y,appearance:s?.characterAppearance,playerRating:gGameEngine.players[0]?.rating,matchStatus:B115.els.matchStatus?.textContent,hud0:document.querySelector('.qol_stat_box[data-slot="0"]')?.getAttribute('data-rating'),hud3:document.querySelector('.qol_stat_box[data-slot="3"]')?.getAttribute('data-rating'),low:BomberCharacter.skillFromRating(400),high:BomberCharacter.skillFromRating(950)}});
 console.log('SIM_PROFILE',JSON.stringify(sim));if(sim.role!=='simulated'||!sim.name||sim.rating<400||sim.rating>1000||!(sim.skill>0)||sim.x!==15||sim.y!==11||!sim.appearance||sim.playerRating!==500||sim.hud0!=='500'||!sim.hud3||!(sim.high>sim.low)||!sim.matchStatus.includes('RatingCI'))throw new Error('simulated profile/skill/rating/spawn invalid');
 await page.evaluate(()=>{localStorage.setItem('BombermanRatingV1','500');gGameEngine.menu.setMode('single')});await sleep(140);await page.evaluate(()=>gGameEngine.gameOver('win'));await sleep(80);const win=await page.evaluate(()=>BomberCharacter.getRating());console.log('RATING_WIN',win);if(win!==510)throw new Error('win did not add 10');
 await page.evaluate(()=>{localStorage.setItem('BombermanRatingV1','500');gGameEngine.menu.setMode('single')});await sleep(140);await page.evaluate(()=>gGameEngine.beginSpectating());await sleep(80);const loss=await page.evaluate(()=>BomberCharacter.getRating());console.log('RATING_LOSS',loss);if(loss!==490)throw new Error('loss did not subtract 10');
 await page.evaluate(()=>{BomberCharacter.setRating(1000);gGameEngine.menu.setMode('single')});await sleep(100);await page.evaluate(()=>gGameEngine.gameOver('win'));await sleep(70);const max=await page.evaluate(()=>BomberCharacter.getRating());if(max!==1000)throw new Error('rating exceeded 1000 max');
 if(errors.length)throw new Error('browser errors: '+errors.join(' | '));console.log('CHARACTER_RATING_SMOKE PASS');
}finally{await context.close().catch(()=>{});await browser.close().catch(()=>{})}
